// Returns 5–6 Q&A entries suitable for on-page FAQ + FAQPage JSON-LD.
// Mixes clinic-specific (address, boka) with evergreen (vad kostar, hur går det till).
export function getClinicFaq(clinic: Clinic, city: City): { q: string; a: string }[] {
  const serviceName = serviceLabels[clinic.services[0]].singular.toLowerCase();
  const price = priceLevelInfo[clinic.priceLevel];

  return [
    {
      q: `Var ligger ${clinic.name}?`,
      a: `${clinic.name} finns på ${clinic.street}, ${clinic.postal} i stadsdelen ${clinic.neighborhood}, ${city.name}.`,
    },
    {
      q: `Hur bokar jag tid hos ${clinic.name}?`,
      a: clinic.bookingUrl
        ? `Du kan boka tid online direkt via klinikens bokningssystem${
            clinic.phone ? ` eller ringa ${clinic.phone}` : ""
          }.`
        : clinic.phone
          ? `Ring ${clinic.phone} för att boka tid. Kliniken har inte online-bokning i skrivande stund.`
          : `Kontakta kliniken direkt via deras webbsida för att boka tid.`,
    },
    {
      q: `Vad kostar en behandling hos ${clinic.name}?`,
      a: `${clinic.name} ligger på prisnivå ${price.dots} (${price.label}) – ${price.range} för en standardbehandling. Första besöket är ofta något längre och kan kosta mer. Kontakta kliniken för aktuell prislista.`,
    },
    {
      q: `Vad händer vid mitt första besök?`,
      a: `Vid första besöket gör ${serviceName}en en anamnes (samtal om dina besvär), följt av en fysisk undersökning för att lokalisera orsaken. Därefter påbörjas behandling och du får med dig råd om träning eller ergonomi. Räkna med 45–60 minuter.`,
    },
    {
      q: `Är ${clinic.name} legitimerad vårdgivare?`,
      a: `Ja. ${clinic.name} drivs av legitimerad ${serviceName} registrerad hos Socialstyrelsen. Nakima verifierar alla kliniker innan de publiceras i katalogen.`,
    },
    {
      q: `Kan jag använda friskvårdsbidrag hos ${clinic.name}?`,
      a: `Massage täcks av friskvårdsbidraget hos de flesta arbetsgivare. Naprapati och kiropraktik räknas normalt som sjukvård och täcks inte av friskvårdsbidrag, men kan vara avdragsgillt via privat vårdförsäkring. Kontrollera med kliniken och din arbetsgivare.`,
    },
  ];
}
